SELECT p.product_id AS productId, p.product_name AS productName, p.price AS price, p.sales_status AS salesStatus, p.trade_type AS tradeType, p.view_count AS viewCount, p.like_count AS likeCount, p.created_at AS createdAt, p.seller_id AS sellerId, p.main_image_url AS mainImageUrl FROM products p
AND p.product_name LIKE CONCAT('%', #{keyword}, '%')
AND p.sales_status = #{salesStatus}
ORDER BY p.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM products p
AND p.product_name LIKE CONCAT('%', #{keyword}, '%')
AND p.sales_status = #{salesStatus}

SELECT COUNT(*)
FROM products
WHERE sales_status = #{salesStatus}
